<style>
.detail-backdrop{display:flex;opacity:0;visibility:hidden;pointer-events:none;transition:opacity .28s ease,visibility .28s ease}.detail-backdrop.open{display:flex;opacity:1;visibility:visible;pointer-events:auto}.detail-backdrop .detail-modal{transform:translateY(18px) scale(.96);opacity:0;transition:transform .32s cubic-bezier(.22,1,.36,1),opacity .24s ease}.detail-backdrop.open .detail-modal{transform:translateY(0) scale(1);opacity:1}.detail-bar span{transition:width .75s cubic-bezier(.22,1,.36,1)}.project{animation:projectEnter .45s cubic-bezier(.22,1,.36,1) both}.project:nth-child(2){animation-delay:.04s}.project:nth-child(3){animation-delay:.08s}.project:nth-child(4){animation-delay:.12s}.project:nth-child(5){animation-delay:.16s}.project:nth-child(6){animation-delay:.20s}.project:nth-child(7){animation-delay:.24s}.project:nth-child(8){animation-delay:.28s}@keyframes projectEnter{from{opacity:0;transform:translateY(12px) scale(.985)}to{opacity:1;transform:translateY(0) scale(1)}}
.detail-modal{width:min(1100px,100%);max-height:92vh;overflow:auto}.detail-layout{display:grid;grid-template-columns:minmax(0,1fr) minmax(360px,.9fr);gap:18px;margin-top:24px}.detail-layout-left,.detail-layout-right{min-width:0}.detail-layout-left>.detail-grid{margin-top:0}.detail-layout-left>.detail-section{margin-top:18px}.detail-layout-left>.detail-progress{margin-top:18px}.detail-layout-left>.detail-hint{margin-top:18px}.detail-gallery{margin:0}.detail-gallery-head,.detail-map-head{display:flex;align-items:center;justify-content:space-between;gap:12px;margin:0 0 9px}.detail-gallery-title,.detail-map-title{font-size:11px;margin:0;color:#cbd5e1;text-transform:uppercase;letter-spacing:.1em}.detail-gallery-count{font-size:10px;color:#64748b}.gallery-stage{position:relative;overflow:hidden;border:1px solid #1e293b;border-radius:16px;background:#050914;aspect-ratio:16/10;display:flex;align-items:center;justify-content:center}.gallery-main{width:100%;height:100%;object-fit:cover;display:block;cursor:zoom-in;transition:transform .28s ease,filter .28s ease}.gallery-stage:hover .gallery-main{transform:scale(1.055);filter:brightness(1.06)}.gallery-empty{color:#64748b;font-size:12px;text-align:center;padding:30px}.gallery-arrow{position:absolute;z-index:2;top:50%;transform:translateY(-50%);width:40px;height:40px;border:1px solid rgba(148,163,184,.3);border-radius:50%;background:rgba(2,6,23,.72);color:#f8fafc;font-size:25px;line-height:1;cursor:pointer}.gallery-arrow:hover{background:#0f172a;border-color:#38bdf8}.gallery-arrow.prev{left:12px}.gallery-arrow.next{right:12px}.gallery-thumbs{display:flex;gap:8px;overflow-x:auto;padding:9px 2px 2px}.gallery-thumb{flex:0 0 68px;width:68px;height:48px;padding:0;border:1px solid #334155;border-radius:9px;overflow:hidden;background:#0f172a;cursor:pointer;opacity:.62}.gallery-thumb:hover,.gallery-thumb.active{opacity:1;border-color:#38bdf8;box-shadow:0 0 0 2px rgba(56,189,248,.12)}.gallery-thumb img{width:100%;height:100%;object-fit:cover;display:block}.detail-map{margin-top:18px}.detail-map-wrap{height:255px;border:1px solid #1e293b;border-radius:16px;overflow:hidden;background:#080d17}.detail-project-map{width:100%;height:100%}.detail-map-empty{height:100%;display:flex;align-items:center;justify-content:center;color:#64748b;font-size:12px;padding:20px;text-align:center}.image-lightbox{position:fixed;inset:0;z-index:3000;display:none;align-items:center;justify-content:center;padding:24px;background:rgba(0,0,0,.92);backdrop-filter:blur(10px)}.image-lightbox.open{display:flex}.lightbox-image{max-width:96vw;max-height:92vh;object-fit:contain;display:block;border-radius:8px}.lightbox-close,.lightbox-arrow{position:fixed;z-index:3;border:1px solid rgba(255,255,255,.2);border-radius:50%;background:rgba(15,23,42,.8);color:#fff;cursor:pointer}.lightbox-close{top:18px;right:20px;width:42px;height:42px;font-size:25px}.lightbox-arrow{top:50%;transform:translateY(-50%);width:52px;height:52px;font-size:32px}.lightbox-arrow.prev{left:22px}.lightbox-arrow.next{right:22px}.lightbox-caption{position:fixed;left:50%;bottom:18px;transform:translateX(-50%);color:#cbd5e1;font-size:11px;background:rgba(2,6,23,.7);padding:7px 11px;border-radius:999px;white-space:nowrap}@media(max-width:850px){.detail-layout{grid-template-columns:1fr}.detail-map-wrap{height:300px}}@media(max-width:600px){.detail-modal{padding:22px}.gallery-stage{aspect-ratio:16/11}.lightbox-arrow{width:42px;height:42px;font-size:27px}.lightbox-arrow.prev{left:10px}.lightbox-arrow.next{right:10px}}
</style>
<script src="https://cdn.jsdelivr.net/npm/pusher-js@8.4.0/dist/web/pusher.min.js"></script>
<script>
(() => {
    const endpoint=@json(route('monitor.data'));
    let galleryImages=[]; let galleryIndex=0; let detailMap=null; let detailMarker=null; let realtimeConnected=false; let refreshTimer=null;
    const esc=v=>String(v??'').replace(/[&<>\"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','\"':'&quot;',"'":'&#39;'}[c]));
    const imageUrl=image=>{const p=String(image?.path||'').trim();if(!p)return '';if(p.startsWith('http://')||p.startsWith('https://'))return p;return '/storage/'+p.replace(/^\/+/, '')};
    const progressGradient=p=>{p=Math.max(0,Math.min(100,Number(p)||0));if(p>=100)return'linear-gradient(90deg,#10b981,#34d399)';if(p>=80)return'linear-gradient(90deg,#22c55e,#84cc16)';if(p>=60)return'linear-gradient(90deg,#eab308,#facc15)';if(p>=30)return'linear-gradient(90deg,#f97316,#fbbf24)';return'linear-gradient(90deg,#ef4444,#fb7185)'};
    const animateProjectBars=projects=>{projects.forEach(p=>{const b=document.querySelector(`.project[data-project-id="${Number(p.id)}"] .bar`);if(!b)return;const target=Math.max(0,Math.min(100,Number(p.progress)||0));b.style.background=progressGradient(target);b.style.width='0%';requestAnimationFrame(()=>requestAnimationFrame(()=>{b.style.width=target+'%'}))})};
    const ensureLightbox=()=>{if(document.getElementById('projectImageLightbox'))return;const box=document.createElement('div');box.id='projectImageLightbox';box.className='image-lightbox';box.innerHTML='<button class="lightbox-close" type="button">×</button><button class="lightbox-arrow prev" type="button">‹</button><img class="lightbox-image" alt="Project image"><button class="lightbox-arrow next" type="button">›</button><div class="lightbox-caption"></div>';document.body.appendChild(box);box.addEventListener('click',e=>{if(e.target===box||e.target.classList.contains('lightbox-close'))closeLightbox()});box.querySelector('.lightbox-close').onclick=closeLightbox;box.querySelector('.prev').onclick=()=>moveGallery(-1,true);box.querySelector('.next').onclick=()=>moveGallery(1,true)};
    const renderLightbox=()=>{ensureLightbox();const box=document.getElementById('projectImageLightbox'),img=galleryImages[galleryIndex];if(!img)return;box.querySelector('.lightbox-image').src=imageUrl(img);box.querySelector('.lightbox-image').alt=img.original_name||'Project image';box.querySelector('.lightbox-caption').textContent=`${galleryIndex+1} / ${galleryImages.length}${img.original_name?' · '+img.original_name:''}`};
    const openLightbox=i=>{if(!galleryImages.length)return;galleryIndex=Math.max(0,Math.min(galleryImages.length-1,i));renderLightbox();document.getElementById('projectImageLightbox').classList.add('open');document.body.style.overflow='hidden'};
    const closeLightbox=()=>{const b=document.getElementById('projectImageLightbox');if(b)b.classList.remove('open');document.body.style.overflow=''};
    const moveGallery=(d,lightbox=false)=>{if(galleryImages.length<2)return;galleryIndex=(galleryIndex+d+galleryImages.length)%galleryImages.length;if(lightbox)renderLightbox();else renderGallery()};
    const renderGallery=()=>{const mount=document.getElementById('detailGallery');if(!mount)return;if(!galleryImages.length){mount.innerHTML='<div class="detail-gallery-head"><h3 class="detail-gallery-title">Project Images</h3></div><div class="gallery-stage"><div class="gallery-empty">Belum ada gambar project.</div></div>';return}const img=galleryImages[galleryIndex];mount.innerHTML=`<div class="detail-gallery-head"><h3 class="detail-gallery-title">Project Images</h3><span class="detail-gallery-count">${galleryIndex+1} / ${galleryImages.length}</span></div><div class="gallery-stage"><img class="gallery-main" src="${esc(imageUrl(img))}" alt="${esc(img.original_name||'Project image')}"><button class="gallery-arrow prev" type="button">‹</button><button class="gallery-arrow next" type="button">›</button></div><div class="gallery-thumbs">${galleryImages.map((x,i)=>`<button class="gallery-thumb ${i===galleryIndex?'active':''}" type="button" data-i="${i}"><img src="${esc(imageUrl(x))}" alt=""></button>`).join('')}</div>`;mount.querySelector('.gallery-main').onclick=()=>openLightbox(galleryIndex);mount.querySelector('.prev').onclick=()=>moveGallery(-1);mount.querySelector('.next').onclick=()=>moveGallery(1);mount.querySelectorAll('.gallery-thumb').forEach(b=>b.onclick=()=>{galleryIndex=Number(b.dataset.i);renderGallery()})};
    const renderDetailMap=project=>{const mount=document.getElementById('detailProjectMap');if(!mount)return;const ll=project?.latlong;const lat=Number(ll?.lat),lng=Number(ll?.lng);if(!Number.isFinite(lat)||!Number.isFinite(lng)){mount.innerHTML='<div class="detail-map-empty">Lokasi project belum memiliki koordinat.</div>';if(detailMap){detailMap.remove();detailMap=null;detailMarker=null}return}if(detailMap)detailMap.remove();mount.innerHTML='<div class="detail-project-map"></div>';detailMap=L.map(mount.querySelector('.detail-project-map'),{zoomControl:true,attributionControl:true}).setView([lat,lng],15);L.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png',{maxZoom:19,attribution:'&copy; OpenStreetMap'}).addTo(detailMap);detailMarker=L.marker([lat,lng]).addTo(detailMap).bindPopup(`<strong>${esc(project.name)}</strong><br>${esc(project.location||'')}`).openPopup();setTimeout(()=>detailMap?.invalidateSize(),80)};
    const buildDetailLayout=()=>{const modal=document.querySelector('#projectDetail .detail-modal');if(!modal||modal.querySelector('.detail-layout'))return;const grid=modal.querySelector('.detail-grid'),progress=modal.querySelector('.detail-progress'),sections=[...modal.querySelectorAll('.detail-section')],hint=modal.querySelector('.detail-hint');const layout=document.createElement('div');layout.className='detail-layout';const left=document.createElement('div');left.className='detail-layout-left';const right=document.createElement('div');right.className='detail-layout-right';const gallery=document.createElement('div');gallery.id='detailGallery';gallery.className='detail-gallery';const map=document.createElement('div');map.className='detail-map';map.innerHTML='<div class="detail-map-head"><h3 class="detail-map-title">Project Location</h3><span class="detail-gallery-count">Pin di tengah lokasi project</span></div><div id="detailProjectMap" class="detail-map-wrap"></div>';right.append(gallery,map);if(grid)left.append(grid);if(progress)left.append(progress);sections.forEach(x=>left.append(x));if(hint)left.append(hint);layout.append(left,right);const anchor=modal.querySelector('.detail-client');anchor?anchor.after(layout):modal.append(layout)};
    const loadProject=async id=>{let project=(window.__monitorProjects||[]).find(p=>Number(p.id)===Number(id));if(!project){try{const r=await fetch(endpoint,{headers:{Accept:'application/json'},cache:'no-store'});const d=await r.json();window.__monitorProjects=d.projects||[];project=window.__monitorProjects.find(p=>Number(p.id)===Number(id))}catch(e){console.error('Project detail gagal dimuat:',e)}}if(!project)return;galleryImages=Array.isArray(project.images)?project.images.slice().sort((a,b)=>Number(a.sort_order||0)-Number(b.sort_order||0)):[];galleryIndex=0;renderGallery();renderDetailMap(project);const progress=Math.max(0,Math.min(100,Number(project.progress)||0));const progressBar=document.getElementById('detailProgressBar');if(progressBar){progressBar.style.width='0%';requestAnimationFrame(()=>requestAnimationFrame(()=>{progressBar.style.width=progress+'%'}))}};
    const buildDetailLayoutAndSync=()=>{const modal=document.getElementById('projectDetail');if(!modal?.classList.contains('open'))return;buildDetailLayout();const id=Number(modal.dataset.projectId||0);if(id)loadProject(id)};
    const observer=new MutationObserver(buildDetailLayoutAndSync);const detail=document.getElementById('projectDetail');if(detail)observer.observe(detail,{attributes:true,attributeFilter:['class','data-project-id']});
    document.addEventListener('click',e=>{const card=e.target.closest('.project[data-project-id]');if(card){setTimeout(()=>{const modal=document.getElementById('projectDetail');if(modal){modal.dataset.projectId=card.dataset.projectId;buildDetailLayoutAndSync()}},30)}});
    document.addEventListener('keydown',e=>{if(!document.getElementById('projectImageLightbox')?.classList.contains('open'))return;if(e.key==='ArrowLeft')moveGallery(-1,true);if(e.key==='ArrowRight')moveGallery(1,true);if(e.key==='Escape')closeLightbox()});
    window.__monitorProjects=window.__monitorProjects||[];
    const refreshMonitor=async()=>{try{const r=await fetch(endpoint,{headers:{Accept:'application/json'},cache:'no-store'});if(!r.ok)return;const d=await r.json();window.__monitorProjects=d.projects||[];if(typeof render==='function')render(d.projects||[],d.summary||null);if(typeof renderMap==='function')renderMap(d.projects||[]);animateProjectBars(d.projects||[]);buildDetailLayoutAndSync()}catch(e){console.error('Monitor refresh gagal:',e)}};
    const pusher=new Pusher(@json(env('REVERB_APP_KEY')), {cluster:'mt1',wsHost:@json(env('REVERB_HOST','127.0.0.1')),wsPort:Number(@json(env('REVERB_PORT',8085))),wssPort:Number(@json(env('REVERB_PORT',8085))),forceTLS:@json(env('REVERB_SCHEME','http'))==='https',enabledTransports:['ws','wss'],disableStats:true});
    const channel=pusher.subscribe('monitor');channel.bind('project.updated',refreshMonitor);pusher.connection.bind('connected',()=>{realtimeConnected=true;console.info('Monitor realtime terhubung ke Reverb.');});pusher.connection.bind('disconnected',()=>{realtimeConnected=false});pusher.connection.bind('error',e=>console.error('Koneksi Reverb gagal:',e));
    refreshTimer=setInterval(()=>{if(!realtimeConnected)refreshMonitor()},5000);
})();
</script>